import numpy as np,cv2,json,math
from scipy import ndimage as ndi
from PIL import Image
PX=227.1845/1024
# Extract nested inset contours. Each component is filled with one connected walk.
def simplify(a,eps=.65):
 return cv2.approxPolyDP(np.asarray(a,np.float32).reshape(-1,1,2),eps,False).reshape(-1,2)
def plan_component(mask,spacing=5.0,radius=3.4):
 dist=cv2.distanceTransform(mask.astype(np.uint8),cv2.DIST_L2,cv2.DIST_MASK_PRECISE)
 # Inset levels with the final small islands included.
 loops=[]
 for lev in np.arange(radius,dist.max()+.01,spacing):
  cs,_=cv2.findContours((dist>=lev).astype(np.uint8),cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_NONE)
  for c in cs:
   a=simplify(c[:,0,:],.5)
   if len(a)>1: loops.append({'xy':a,'lev':float(lev),'children':[]})
 if not loops:return None
 # Attach each inner loop to a nearest loop at a shallower level; multiple outside contours join by shortest safe route later.
 for i,l in enumerate(loops):
  if i==0:continue
  best=None
  for j in range(i):
   if loops[j]['lev']>=l['lev']: continue
   a=loops[j]['xy'];b=l['xy'];d=((a[:,None,:]-b[None,:,:])**2).sum(2);q=np.unravel_index(d.argmin(),d.shape)
   if best is None or d[q]<best[0]:best=(float(d[q]),j,*q)
  if best is None:
   # rare disconnected at first erosion: nearest first-level loop
   for j in range(i):
    a=loops[j]['xy'];b=l['xy'];d=((a[:,None,:]-b[None,:,:])**2).sum(2);q=np.unravel_index(d.argmin(),d.shape)
    if best is None or d[q]<best[0]:best=(float(d[q]),j,*q)
  _,j,ia,ib=best;loops[j]['children'].append((ia,i,ib))
 out=[]
 def walk(i,start):
  l=loops[i];a=l['xy'];ch={}
  for ia,j,ib in l['children']:ch.setdefault(ia,[]).append((j,ib))
  for k in range(len(a)+1):
   idx=(k+start)%len(a);out.append(a[idx])
   if k<len(a):
    for j,ib in ch.get(idx,[]):
     walk(j,ib);out.append(a[idx])
 walk(0,0)
 return np.array(out,float)
def make_plan(spacing=5.0,radius=3.4,min_area=40):
 labels=np.load('/app/output/labels.npy');plan=[]
 # Paint each class separately. Regions do not depend on overpainting.
 for color in [9,6,8,4,2,0,1,3,5,7]:
  mask=labels==color
  # smooth subpixel fluctuations before contour extraction
  mask=ndi.binary_fill_holes(mask) if False else mask
  comps,n=ndi.label(mask);sizes=np.bincount(comps.ravel())
  for k in np.argsort(sizes[1:])[::-1]+1:
   if sizes[k]<min_area:continue
   ys,xs=np.where(comps==k);x0,x1=xs.min(),xs.max();y0,y1=ys.min(),ys.max()
   m=comps[y0:y1+1,x0:x1+1]==k;m=np.pad(m,2)
   xy=plan_component(m,spacing,radius)
   if xy is None:continue
   xy+=np.array([x0-2,y0-2]);xy=(xy+.5)*PX
   plan.append({'color':color,'xy':xy.tolist(),'area':int(sizes[k])})
  print(color,'strokes',sum(p['color']==color for p in plan),flush=True)
 return plan
if __name__=='__main__':
 plan=make_plan();json.dump(plan,open('/app/output/plan.json','w'))
 print('strokes',len(plan),'length mm',sum(np.linalg.norm(np.diff(p['xy'],axis=0),axis=1).sum() for p in plan))
 # Geometric preview with capsule footprints
 out=np.full((1024,1024,3),[248,244,236],np.uint8);pa=np.array([w['rgb'] for w in json.load(open('/app/instance.json'))['wells']['wells']])*255
 for p in plan:
  pts=np.round(np.array(p['xy'])/PX-.5).astype(np.int32);cv2.polylines(out,[pts],False,pa[p['color']].tolist(),7,cv2.LINE_AA)
 Image.fromarray(out).save('/app/output/plan_preview.png')
